cat > /tmp/trdsql_src/main.go << 'EOF'
package main

import (
	"bufio"
	"database/sql"
	"encoding/csv"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	_ "github.com/mattn/go-sqlite3"
	"gopkg.in/yaml.v3"
)

const VERSION = "trdsql version devel"

type Options struct {
	InputFormat    string
	OutputFormat   string
	InputDelim     string
	OutputDelim    string
	HasHeader      bool
	Help           bool
	Version        bool
	Query          string
	QueryFile      string
	InputFile      string
	OutputFile     string
	OutputHeader   bool
	AnalyzeFile    string
	ShowHelp       bool
	Analyze        bool
	AutoDetect     bool
	SkipHeader     int
	PrereadRows    int
	LimitRows      int
	AddRowNum      bool
	NullValue      string
	OutputNull     string
	Debug          bool
	Driver         string
	DSN            string
	Compression    string
	CRLF           bool
	QuoteAll       bool
	Quote          string
	OutWithoutGuess bool
}

func main() {
	opts := parseFlags()

	if opts.Version {
		fmt.Println(VERSION)
		return
	}

	if opts.Help {
		showUsage()
		os.Exit(2)
	}

	if opts.AnalyzeFile != "" {
		analyzeFile(opts.AnalyzeFile, opts)
		return
	}

	if opts.Analyze {
		if flag.NArg() > 0 {
			analyzeFile(flag.Arg(0), opts)
		}
		return
	}

	// Get query
	query := opts.Query
	if opts.QueryFile != "" {
		data, err := os.ReadFile(opts.QueryFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading query file: %v\n", err)
			os.Exit(1)
		}
		query = strings.TrimSpace(string(data))
	} else if query == "" && flag.NArg() > 0 {
		query = flag.Arg(0)
	}

	if query == "" && opts.InputFile == "" {
		showUsage()
		os.Exit(2)
	}

	// Execute query
	if query != "" {
		result, err := executeQuery(query, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		// Output result
		if opts.OutputFile != "" {
			err = writeToFile(result, opts)
		} else {
			err = writeToStdout(result, opts)
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
}

func parseFlags() Options {
	opts := Options{
		InputDelim:   ",",
		OutputDelim:  ",",
		InputFormat:  "guess",
		OutputFormat: "csv",
		Quote:        "\"",
		PrereadRows:  1,
		AutoDetect:   true,
		Driver:       "sqlite3",
	}

	flag.StringVar(&opts.AnalyzeFile, "A", "", "analyze the file but only suggest SQL.")
	flag.StringVar(&opts.AnalyzeFile, "a", "", "analyze the file and suggest SQL.")
	flag.BoolVar(&opts.Analyze, "a", false, "analyze the file and suggest SQL.")
	flag.StringVar(&opts.QueryFile, "q", "", "read query from the specified file.")
	flag.StringVar(&opts.InputFile, "t", "", "read table name from the specified file.")
	flag.BoolVar(&opts.Help, "help", false, "display usage information.")
	flag.BoolVar(&opts.Version, "version", false, "display version information.")
	flag.BoolVar(&opts.HasHeader, "ih", false, "the first line is interpreted as column names(CSV only).")
	flag.StringVar(&opts.InputDelim, "id", ",", "field delimiter for input.")
	flag.StringVar(&opts.InputFormat, "ig", "guess", "guess format from extension.")
	flag.StringVar(&opts.OutputFormat, "ocsv", "csv", "CSV format for output.")
	flag.StringVar(&opts.OutputFormat, "ojson", "json", "JSON format for output.")
	flag.StringVar(&opts.OutputFormat, "ojsonl", "jsonl", "JSON lines format for output.")
	flag.StringVar(&opts.OutputFormat, "oltsv", "ltsv", "LTSV format for output.")
	flag.StringVar(&opts.OutputFormat, "omd", "md", "Markdown format for output.")
	flag.StringVar(&opts.OutputFormat, "oat", "at", "ASCII Table format for output.")
	flag.StringVar(&opts.OutputFormat, "oyaml", "yaml", "YAML format for output.")
	flag.StringVar(&opts.OutputFormat, "oraw", "raw", "Raw format for output.")
	flag.StringVar(&opts.OutputFormat, "ovf", "vf", "Vertical format for output.")
	flag.StringVar(&opts.OutputFormat, "otbln", "tbln", "TBLN format for output.")
	flag.StringVar(&opts.OutputDelim, "od", ",", "field delimiter for output.")
	flag.StringVar(&opts.OutputFile, "out", "", "output file name.")
	flag.BoolVar(&opts.OutputHeader, "oh", false, "output column name as header.")
	flag.IntVar(&opts.SkipHeader, "is", 0, "skip header row.")
	flag.IntVar(&opts.PrereadRows, "ir", 1, "number of rows to preread.")
	flag.IntVar(&opts.LimitRows, "ilr", 0, "limited number of rows to read.")
	flag.BoolVar(&opts.AddRowNum, "inum", false, "add row number column.")
	flag.StringVar(&opts.NullValue, "inull", "", "value(string) to convert to null on input.")
	flag.StringVar(&opts.OutputNull, "onull", "", "value(string) to convert from null on output.")
	flag.BoolVar(&opts.Debug, "debug", false, "debug print.")
	flag.StringVar(&opts.Driver, "driver", "sqlite3", "database driver.")
	flag.StringVar(&opts.DSN, "dsn", "", "database driver specific data source name.")
	flag.StringVar(&opts.Compression, "oz", "", "output compression format.")
	flag.BoolVar(&opts.CRLF, "ocrlf", false, "use CRLF for output.")
	flag.BoolVar(&opts.QuoteAll, "oaq", false, "enclose all fields in quotes for output.")
	flag.StringVar(&opts.Quote, "oq", "\"", "quote character for output.")
	flag.BoolVar(&opts.OutWithoutGuess, "out-without-guess", false, "output without guessing (when using -out).")

	flag.Parse()

	// Check for input format flags
	if flag.Lookup("icsv") != nil && flag.Lookup("icsv").Changed {
		opts.InputFormat = "csv"
	}
	if flag.Lookup("ijson") != nil && flag.Lookup("ijson").Changed {
		opts.InputFormat = "json"
	}
	if flag.Lookup("iltsv") != nil && flag.Lookup("iltsv").Changed {
		opts.InputFormat = "ltsv"
	}
	if flag.Lookup("iyaml") != nil && flag.Lookup("iyaml").Changed {
		opts.InputFormat = "yaml"
	}
	if flag.Lookup("itext") != nil && flag.Lookup("itext").Changed {
		opts.InputFormat = "text"
	}
	if flag.Lookup("iwidth") != nil && flag.Lookup("iwidth").Changed {
		opts.InputFormat = "width"
	}
	if flag.Lookup("itbln") != nil && flag.Lookup("itbln").Changed {
		opts.InputFormat = "tbln"
	}

	// Check for output format flags
	if flag.Lookup("ocsv") != nil && flag.Lookup("ocsv").Changed {
		opts.OutputFormat = "csv"
	}
	if flag.Lookup("ojson") != nil && flag.Lookup("ojson").Changed {
		opts.OutputFormat = "json"
	}
	if flag.Lookup("ojsonl") != nil && flag.Lookup("ojsonl").Changed {
		opts.OutputFormat = "jsonl"
	}
	if flag.Lookup("oltsv") != nil && flag.Lookup("oltsv").Changed {
		opts.OutputFormat = "ltsv"
	}
	if flag.Lookup("omd") != nil && flag.Lookup("omd").Changed {
		opts.OutputFormat = "md"
	}
	if flag.Lookup("oat") != nil && flag.Lookup("oat").Changed {
		opts.OutputFormat = "at"
	}
	if flag.Lookup("oyaml") != nil && flag.Lookup("oyaml").Changed {
		opts.OutputFormat = "yaml"
	}
	if flag.Lookup("oraw") != nil && flag.Lookup("oraw").Changed {
		opts.OutputFormat = "raw"
	}
	if flag.Lookup("ovf") != nil && flag.Lookup("ovf").Changed {
		opts.OutputFormat = "vf"
	}
	if flag.Lookup("otbln") != nil && flag.Lookup("otbln").Changed {
		opts.OutputFormat = "tbln"
	}

	return opts
}

func showUsage() {
	fmt.Fprintf(os.Stderr, `trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

Usage
	trdsql [OPTIONS] [SQL(SELECT...)]

Options:
  -A string           analyze the file but only suggest SQL.
  -a string           analyze the file and suggest SQL.
  -config string      configuration file location.
  -db string          specify db name of the setting.
  -dblist             display db information.
  -debug              debug print.
  -driver string      database driver.  [ mysql | postgres | sqlite3 | sqlite3_ext ]
  -dsn string         database driver specific data source name.
  -help               display usage information.
  -q string           read query from the specified file.
  -t string           read table name from the specified file.
  -version            display version information.

Input Formats:
  -icsv               CSV format for input.
  -ig                 guess format from extension. (default "true")
  -ijson              JSON format for input.
  -iltsv              LTSV format for input.
  -itbln              TBLN format for input.
  -itext              text format for input.
  -iwidth             width specification format for input.
  -iyaml              YAML format for input.

Input options:
  -id string          field delimiter for input. (default ",")
  -ih                 the first line is interpreted as column names(CSV only).
  -ijq string         jq expression string for input(JSON/JSONL only).
  -ilr int            limited number of rows to read. (default 0)
  -inull value        value(string) to convert to null on input.
  -inum               add row number column.
  -ir int             number of rows to preread. (default 1)
  -is int             skip header row. (default 0)

Output Formats:
  -oat                ASCII Table format for output.
  -ocsv               CSV format for output.
  -ojson              JSON format for output.
  -ojsonl             JSON lines format for output.
  -oltsv              LTSV format for output.
  -omd                Markdown format for output.
  -oraw               Raw format for output.
  -otbln              TBLN format for output.
  -ovf                Vertical format for output.
  -oyaml              YAML format for output.

Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\r\n' instead of '\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"
`)
}

type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func executeQuery(query string, opts Options) (*QueryResult, error) {
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		return nil, err
	}
	defer db.Close()

	// Load files into database
	err = loadFilesIntoDatabase(db, query, opts)
	if err != nil {
		return nil, err
	}

	// Execute query
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	columns, err := rows.Columns()
	if err != nil {
		return nil, err
	}

	result := &QueryResult{
		Columns: columns,
		Rows:    [][]string{},
	}

	for rows.Next() {
		values := make([]interface{}, len(columns))
		valuePtrs := make([]interface{}, len(columns))
		for i := range columns {
			valuePtrs[i] = &values[i]
		}
		if err := rows.Scan(valuePtrs...); err != nil {
			return nil, err
		}

		row := make([]string, len(columns))
		for i, val := range values {
			if val == nil {
				row[i] = ""
			} else {
				row[i] = fmt.Sprintf("%v", val)
			}
		}
		result.Rows = append(result.Rows, row)
	}

	return result, rows.Err()
}

func loadFilesIntoDatabase(db *sql.DB, query string, opts Options) error {
	// Extract table names from query
	tables := extractTableNames(query)

	for _, table := range tables {
		if table == "-" {
			// Read from stdin
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
			err = loadDataIntoTable(db, "-", string(data), opts)
			if err != nil {
				return err
			}
		} else {
			// Read from file
			data, err := os.ReadFile(table)
			if err != nil {
				return err
			}
			err = loadDataIntoTable(db, table, string(data), opts)
			if err != nil {
				return err
			}
		}
	}

	return nil
}

func extractTableNames(query string) []string {
	// Simple extraction - look for FROM keywords
	tables := []string{}
	parts := strings.Fields(strings.ToUpper(query))
	for i, part := range parts {
		if part == "FROM" && i+1 < len(parts) {
			table := strings.Split(parts[i+1], ":")[0]
			table = strings.TrimSuffix(table, ",")
			tables = append(tables, table)
		}
	}
	return tables
}

func loadDataIntoTable(db *sql.DB, tablePath string, data string, opts Options) error {
	// Detect format
	format := opts.InputFormat
	if format == "guess" {
		format = detectFormat(tablePath)
	}

	// Parse data
	rows, columns, err := parseData(format, data, opts)
	if err != nil {
		return err
	}

	if len(rows) == 0 {
		return nil
	}

	// Create table name
	tableName := filepath.Base(tablePath)
	if tablePath == "-" {
		tableName = "stdin"
	}

	// Create table
	err = createTable(db, tableName, columns, rows)
	if err != nil {
		return err
	}

	return nil
}

func detectFormat(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".csv":
		return "csv"
	case ".json", ".jsonl":
		return "json"
	case ".ltsv":
		return "ltsv"
	case ".yaml", ".yml":
		return "yaml"
	case ".tbln":
		return "tbln"
	default:
		return "text"
	}
}

func parseData(format string, data string, opts Options) ([][]string, []string, error) {
	switch format {
	case "csv":
		return parseCSV(data, opts)
	case "json":
		return parseJSON(data, opts)
	case "ltsv":
		return parseLTSV(data, opts)
	case "yaml":
		return parseYAML(data, opts)
	default:
		return parseText(data, opts)
	}
}

func parseCSV(data string, opts Options) ([][]string, []string, error) {
	reader := csv.NewReader(strings.NewReader(data))
	reader.Comma = rune(opts.InputDelim[0])

	var rows [][]string
	var columns []string

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, nil, err
		}
		rows = append(rows, record)
	}

	if len(rows) == 0 {
		return nil, nil, nil
	}

	if opts.HasHeader && len(rows) > 0 {
		columns = rows[0]
		rows = rows[1:]
	} else {
		columns = make([]string, len(rows[0]))
		for i := range columns {
			columns[i] = fmt.Sprintf("c%d", i+1)
		}
	}

	return rows, columns, nil
}

func parseJSON(data string, opts Options) ([][]string, []string, error) {
	var jsonData interface{}
	err := json.Unmarshal([]byte(data), &jsonData)
	if err != nil {
		return nil, nil, err
	}

	var rows [][]string
	var columns []string

	if arr, ok := jsonData.([]interface{}); ok {
		for _, item := range arr {
			if obj, ok := item.(map[string]interface{}); ok {
				if len(columns) == 0 {
					for key := range obj {
						columns = append(columns, key)
					}
				}
				row := make([]string, len(columns))
				for i, col := range columns {
					val := obj[col]
					if val == nil {
						row[i] = ""
					} else {
						row[i] = fmt.Sprintf("%v", val)
					}
				}
				rows = append(rows, row)
			}
		}
	}

	return rows, columns, nil
}

func parseLTSV(data string, opts Options) ([][]string, []string, error) {
	var rows [][]string
	columnSet := make(map[string]bool)
	var columns []string

	scanner := bufio.NewScanner(strings.NewReader(data))
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		obj := make(map[string]string)
		parts := strings.Split(line, "\t")
		for _, part := range parts {
			kv := strings.SplitN(part, ":", 2)
			if len(kv) == 2 {
				key := kv[0]
				obj[key] = kv[1]
				if !columnSet[key] {
					columnSet[key] = true
					columns = append(columns, key)
				}
			}
		}

		row := make([]string, len(columns))
		for i, col := range columns {
			row[i] = obj[col]
		}
		rows = append(rows, row)
	}

	return rows, columns, nil
}

func parseYAML(data string, opts Options) ([][]string, []string, error) {
	var yamlData []interface{}
	err := yaml.Unmarshal([]byte(data), &yamlData)
	if err != nil {
		return nil, nil, err
	}

	var rows [][]string
	var columns []string

	for _, item := range yamlData {
		if obj, ok := item.(map[string]interface{}); ok {
			if len(columns) == 0 {
				for key := range obj {
					columns = append(columns, key)
				}
			}
			row := make([]string, len(columns))
			for i, col := range columns {
				val := obj[col]
				if val == nil {
					row[i] = ""
				} else {
					row[i] = fmt.Sprintf("%v", val)
				}
			}
			rows = append(rows, row)
		}
	}

	return rows, columns, nil
}

func parseText(data string, opts Options) ([][]string, []string, error) {
	return parseCSV(data, opts)
}

func createTable(db *sql.DB, tableName string, columns []string, rows [][]string) error {
	// Create table SQL
	parts := []string{}
	for _, col := range columns {
		parts = append(parts, fmt.Sprintf(`"%s" TEXT`, col))
	}
	createSQL := fmt.Sprintf(`CREATE TABLE "%s" (%s)`, tableName, strings.Join(parts, ","))

	_, err := db.Exec(createSQL)
	if err != nil {
		return err
	}

	// Insert rows
	placeholders := make([]string, len(columns))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	insertSQL := fmt.Sprintf(`INSERT INTO "%s" VALUES (%s)`, tableName, strings.Join(placeholders, ","))

	for _, row := range rows {
		values := make([]interface{}, len(row))
		for i, val := range row {
			values[i] = val
		}
		_, err := db.Exec(insertSQL, values...)
		if err != nil {
			return err
		}
	}

	return nil
}

func writeToStdout(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}
	fmt.Print(output)
	return nil
}

func writeToFile(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}

	err = os.WriteFile(opts.OutputFile, []byte(output), 0644)
	if err != nil {
		return err
	}

	return nil
}

func formatOutput(result *QueryResult, opts Options) (string, error) {
	switch opts.OutputFormat {
	case "csv":
		return formatCSV(result, opts)
	case "json":
		return formatJSON(result, opts)
	case "jsonl":
		return formatJSONL(result, opts)
	case "ltsv":
		return formatLTSV(result, opts)
	case "yaml":
		return formatYAML(result, opts)
	case "md":
		return formatMarkdown(result, opts)
	case "at":
		return formatASCIITable(result, opts)
	case "vf":
		return formatVertical(result, opts)
	case "raw":
		return formatRaw(result, opts)
	default:
		return formatCSV(result, opts)
	}
}

func formatCSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if opts.OutputHeader {
		line := strings.Join(result.Columns, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	for _, row := range result.Rows {
		line := strings.Join(row, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatJSON(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	// Pretty print JSON
	b, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return "", err
	}

	return string(b), nil
}

func formatJSONL(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		b, err := json.Marshal(obj)
		if err != nil {
			return "", err
		}
		output.WriteString(string(b) + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatLTSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		parts := []string{}
		for i, col := range result.Columns {
			parts = append(parts, fmt.Sprintf("%s:%s", col, row[i]))
		}
		output.WriteString(strings.Join(parts, "\t") + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatYAML(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	b, err := yaml.Marshal(data)
	if err != nil {
		return "", err
	}

	return strings.TrimSuffix(string(b), "\n"), nil
}

func formatMarkdown(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("|")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("|\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatASCIITable(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Top border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	// Bottom border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatVertical(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for idx, row := range result.Rows {
		output.WriteString(fmt.Sprintf("---[ %d]", idx+1))
		output.WriteString(strings.Repeat("-", 24) + "\n")

		maxLen := 0
		for _, col := range result.Columns {
			if len(col) > maxLen {
				maxLen = len(col)
			}
		}

		for i, col := range result.Columns {
			output.WriteString(padRight(col, maxLen))
			output.WriteString(" | ")
			output.WriteString(row[i])
			output.WriteString("\n")
		}
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatRaw(result *QueryResult, opts Options) (string, error) {
	return formatCSV(result, opts)
}

func padString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	left := (width - len(s)) / 2
	right := width - len(s) - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func analyzeFile(filepath string, opts Options) {
	data, err := os.ReadFile(filepath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
		return
	}

	format := detectFormat(filepath)
	rows, columns, err := parseData(format, string(data), opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing file: %v\n", err)
		return
	}

	fmt.Printf("The table name is %s.\n", filepath)
	fmt.Printf("The file type is %s.\n", strings.ToUpper(format))
	fmt.Println()
	fmt.Println("Data types:")

	// Print type table
	fmt.Println("+-------------+------+")
	fmt.Println("| column name | type |")
	fmt.Println("+-------------+------+")
	for _, col := range columns {
		fmt.Printf("| %-11s | %4s |\n", col, "text")
	}
	fmt.Println("+-------------+------+")
	fmt.Println()
	fmt.Println("Data samples:")

	// Print sample data
	fmt.Println("+------+-----+------+")
	for _, col := range columns {
		fmt.Printf("| %4s ", col)
	}
	fmt.Println("|")
	fmt.Println("+------+-----+------+")
	if len(rows) > 0 {
		for _, val := range rows[0] {
			fmt.Printf("| %4s ", val)
		}
		fmt.Println("|")
	}
	fmt.Println("+------+-----+------+")
	fmt.Println()
	fmt.Println("Examples:")
	tableName := filepath
	fmt.Printf("./executable \"SELECT %s FROM %s\"\n", strings.Join(columns, ", "), tableName)
	if len(columns) > 0 {
		fmt.Printf("./executable \"SELECT %s FROM %s WHERE %s = '%s'\"\n", strings.Join(columns, ", "), tableName, columns[0], columns[0])
	}
