type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func executeQuery(query string, opts Options) (*QueryResult, error) {
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		return nil, err
	}
	defer db.Close()

	// Load files into database
	err = loadFilesIntoDatabase(db, query, opts)
	if err != nil {
		return nil, err
	}

	// Execute query
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	columns, err := rows.Columns()
	if err != nil {
		return nil, err
	}

	result := &QueryResult{
		Columns: columns,
		Rows:    [][]string{},
	}

	for rows.Next() {
		values := make([]interface{}, len(columns))
		valuePtrs := make([]interface{}, len(columns))
		for i := range columns {
			valuePtrs[i] = &values[i]
		}
		if err := rows.Scan(valuePtrs...); err != nil {
			return nil, err
		}

		row := make([]string, len(columns))
		for i, val := range values {
			if val == nil {
				row[i] = ""
			} else {
				row[i] = fmt.Sprintf("%v", val)
			}
		}
		result.Rows = append(result.Rows, row)
	}

	return result, rows.Err()
}

func loadFilesIntoDatabase(db *sql.DB, query string, opts Options) error {
	// Extract table names from query
	tables := extractTableNames(query)

	for _, table := range tables {
		if table == "-" {
			// Read from stdin
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
			err = loadDataIntoTable(db, "-", string(data), opts)
			if err != nil {
				return err
			}
		} else {
			// Read from file
			data, err := os.ReadFile(table)
			if err != nil {
				return err
			}
			err = loadDataIntoTable(db, table, string(data), opts)
			if err != nil {
				return err
			}
		}
	}

	return nil
}

func extractTableNames(query string) []string {
	// Simple extraction - look for FROM keywords
	tables := []string{}
	parts := strings.Fields(strings.ToUpper(query))
	for i, part := range parts {
		if part == "FROM" && i+1 < len(parts) {
			table := strings.Split(parts[i+1], ":")[0]
			table = strings.TrimSuffix(table, ",")
			tables = append(tables, table)
		}
	}
	return tables
}

func loadDataIntoTable(db *sql.DB, tablePath string, data string, opts Options) error {
	// Detect format
	format := opts.InputFormat
	if format == "guess" {
		format = detectFormat(tablePath)
	}

	// Parse data
	rows, columns, err := parseData(format, data, opts)
	if err != nil {
		return err
	}

	if len(rows) == 0 {
		return nil
	}

	// Create table name
	tableName := filepath.Base(tablePath)
	if tablePath == "-" {
		tableName = "stdin"
	}

	// Create table
	err = createTable(db, tableName, columns, rows)
	if err != nil {
		return err
	}

	return nil
}

func detectFormat(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".csv":
		return "csv"
	case ".json", ".jsonl":
		return "json"
	case ".ltsv":
		return "ltsv"
	case ".yaml", ".yml":
		return "yaml"
	case ".tbln":
		return "tbln"
	default:
		return "text"
	}
}

func parseData(format string, data string, opts Options) ([][]string, []string, error) {
	switch format {
	case "csv":
		return parseCSV(data, opts)
	case "json":
		return parseJSON(data, opts)
	case "ltsv":
		return parseLTSV(data, opts)
	case "yaml":
		return parseYAML(data, opts)
	default:
		return parseText(data, opts)
	}
}

func parseCSV(data string, opts Options) ([][]string, []string, error) {
	reader := csv.NewReader(strings.NewReader(data))
	reader.Comma = rune(opts.InputDelim[0])

	var rows [][]string
	var columns []string

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, nil, err
		}
		rows = append(rows, record)
	}

	if len(rows) == 0 {
		return nil, nil, nil
	}

	if opts.HasHeader && len(rows) > 0 {
		columns = rows[0]
		rows = rows[1:]
	} else {
		columns = make([]string, len(rows[0]))
		for i := range columns {
			columns[i] = fmt.Sprintf("c%d", i+1)
		}
	}

	return rows, columns, nil
}

func parseJSON(data string, opts Options) ([][]string, []string, error) {
	var jsonData interface{}
	err := json.Unmarshal([]byte(data), &jsonData)
	if err != nil {
		return nil, nil, err
	}

	var rows [][]string
	var columns []string

	if arr, ok := jsonData.([]interface{}); ok {
		for _, item := range arr {
			if obj, ok := item.(map[string]interface{}); ok {
				if len(columns) == 0 {
					for key := range obj {
						columns = append(columns, key)
					}
				}
				row := make([]string, len(columns))
				for i, col := range columns {
					val := obj[col]
					if val == nil {
						row[i] = ""
					} else {
						row[i] = fmt.Sprintf("%v", val)
					}
				}
				rows = append(rows, row)
			}
		}
	}

	return rows, columns, nil
}

func parseLTSV(data string, opts Options) ([][]string, []string, error) {
	var rows [][]string
	columnSet := make(map[string]bool)
	var columns []string

	scanner := bufio.NewScanner(strings.NewReader(data))
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		obj := make(map[string]string)
		parts := strings.Split(line, "\t")
		for _, part := range parts {
			kv := strings.SplitN(part, ":", 2)
			if len(kv) == 2 {
				key := kv[0]
				obj[key] = kv[1]
				if !columnSet[key] {
					columnSet[key] = true
					columns = append(columns, key)
				}
			}
		}

		row := make([]string, len(columns))
		for i, col := range columns {
			row[i] = obj[col]
		}
		rows = append(rows, row)
	}

	return rows, columns, nil
}

func parseYAML(data string, opts Options) ([][]string, []string, error) {
	var yamlData []interface{}
	err := yaml.Unmarshal([]byte(data), &yamlData)
	if err != nil {
		return nil, nil, err
	}

	var rows [][]string
	var columns []string

	for _, item := range yamlData {
		if obj, ok := item.(map[string]interface{}); ok {
			if len(columns) == 0 {
				for key := range obj {
					columns = append(columns, key)
				}
			}
			row := make([]string, len(columns))
			for i, col := range columns {
				val := obj[col]
				if val == nil {
					row[i] = ""
				} else {
					row[i] = fmt.Sprintf("%v", val)
				}
			}
			rows = append(rows, row)
		}
	}

	return rows, columns, nil
}

func parseText(data string, opts Options) ([][]string, []string, error) {
	return parseCSV(data, opts)
}

func createTable(db *sql.DB, tableName string, columns []string, rows [][]string) error {
	// Create table SQL
	parts := []string{}
	for _, col := range columns {
		parts = append(parts, fmt.Sprintf(`"%s" TEXT`, col))
	}
	createSQL := fmt.Sprintf(`CREATE TABLE "%s" (%s)`, tableName, strings.Join(parts, ","))

	_, err := db.Exec(createSQL)
	if err != nil {
		return err
	}

	// Insert rows
	placeholders := make([]string, len(columns))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	insertSQL := fmt.Sprintf(`INSERT INTO "%s" VALUES (%s)`, tableName, strings.Join(placeholders, ","))

	for _, row := range rows {
		values := make([]interface{}, len(row))
		for i, val := range row {
			values[i] = val
		}
		_, err := db.Exec(insertSQL, values...)
		if err != nil {
			return err
		}
	}

	return nil
}

func writeToStdout(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}
	fmt.Print(output)
	return nil
}

func writeToFile(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}

	err = os.WriteFile(opts.OutputFile, []byte(output), 0644)
	if err != nil {
		return err
	}

	return nil
}

func formatOutput(result *QueryResult, opts Options) (string, error) {
	switch opts.OutputFormat {
	case "csv":
		return formatCSV(result, opts)
	case "json":
		return formatJSON(result, opts)
	case "jsonl":
		return formatJSONL(result, opts)
	case "ltsv":
		return formatLTSV(result, opts)
	case "yaml":
		return formatYAML(result, opts)
	case "md":
		return formatMarkdown(result, opts)
	case "at":
		return formatASCIITable(result, opts)
	case "vf":
		return formatVertical(result, opts)
	case "raw":
		return formatRaw(result, opts)
	default:
		return formatCSV(result, opts)
	}
}

func formatCSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if opts.OutputHeader {
		line := strings.Join(result.Columns, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	for _, row := range result.Rows {
		line := strings.Join(row, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatJSON(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	// Pretty print JSON
	b, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return "", err
	}

	return string(b), nil
}

func formatJSONL(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		b, err := json.Marshal(obj)
		if err != nil {
			return "", err
		}
		output.WriteString(string(b) + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatLTSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		parts := []string{}
		for i, col := range result.Columns {
			parts = append(parts, fmt.Sprintf("%s:%s", col, row[i]))
		}
		output.WriteString(strings.Join(parts, "\t") + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatYAML(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	b, err := yaml.Marshal(data)
	if err != nil {
		return "", err
	}

	return strings.TrimSuffix(string(b), "\n"), nil
}

func formatMarkdown(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("|")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("|\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatASCIITable(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Top border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	// Bottom border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatVertical(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for idx, row := range result.Rows {
		output.WriteString(fmt.Sprintf("---[ %d]", idx+1))
		output.WriteString(strings.Repeat("-", 24) + "\n")

		maxLen := 0
		for _, col := range result.Columns {
			if len(col) > maxLen {
				maxLen = len(col)
			}
		}

		for i, col := range result.Columns {
			output.WriteString(padRight(col, maxLen))
			output.WriteString(" | ")
			output.WriteString(row[i])
			output.WriteString("\n")
		}
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatRaw(result *QueryResult, opts Options) (string, error) {
	return formatCSV(result, opts)
}

func padString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	left := (width - len(s)) / 2
	right := width - len(s) - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

