	flag.String("ijq", "", "jq expression string for input(JSON/JSONL only).")
	flag.Bool("onowrap", false, "do not wrap long lines(at/md only).")

	flag.Parse()

	// Check for input format flags
	if *icsv {
		opts.InputFormat = "csv"
	} else if *ijson {
		opts.InputFormat = "json"
