type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func executeQuery(query string, opts Options) (*QueryResult, error) {
	// Extract table information from query
	tables := extractTableInfo(query)

	data := make(map[string]Table)
	for _, table := range tables {
		t, columns, err := loadTable(table.Name, opts)
		if err != nil {
			return nil, err
		}
		data[table.Name] = t
	}

	// For now, implement a simple row-by-row filter and projection
	result := processQuery(query, data)

	// Format result
	queryResult := &QueryResult{
		Columns: result.Columns,
		Rows:    make([][]string, len(result.Rows)),
	}

	for i, row := range result.Rows {
		strRow := make([]string, len(result.Columns))
		for j, col := range result.Columns {
			val := row[col]
			if val == nil {
				strRow[j] = ""
			} else {
				strRow[j] = fmt.Sprintf("%v", val)
			}
		}
		queryResult.Rows[i] = strRow
	}

	return queryResult, nil
}

type TableInfo struct {
	Name string
}

func extractTableInfo(query string) []TableInfo {
	tables := []TableInfo{}
	upQuery := strings.ToUpper(query)
	parts := strings.Fields(upQuery)

	for i, part := range parts {
		if part == "FROM" && i+1 < len(parts) {
			tableName := strings.Split(parts[i+1], ":")[0]
			tableName = strings.TrimSuffix(tableName, ",")
			tables = append(tables, TableInfo{Name: tableName})
		} else if part == "JOIN" && i+1 < len(parts) {
			tableName := strings.Split(parts[i+1], ":")[0]
			tableName = strings.TrimSuffix(tableName, ",")
			tables = append(tables, TableInfo{Name: tableName})
		}
	}

	return tables
}

func loadTable(tableName string, opts Options) (Table, []string, error) {
	var data string
	var err error

	if tableName == "-" {
		// Read from stdin
		allBytes, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, nil, err
		}
		data = string(allBytes)
	} else {
		// Read from file
		allBytes, err := os.ReadFile(tableName)
		if err != nil {
			return nil, nil, err
		}
		data = string(allBytes)
	}

	format := opts.InputFormat
	if format == "guess" {
		format = detectFormat(tableName)
	}

	return parseData(format, data, opts)
}

func detectFormat(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".csv":
		return "csv"
	case ".json", ".jsonl":
		return "json"
	case ".ltsv":
		return "ltsv"
	case ".yaml", ".yml":
		return "yaml"
	case ".tbln":
		return "tbln"
	default:
		return "text"
	}
}

func parseData(format string, data string, opts Options) (Table, []string, error) {
	switch format {
	case "csv":
		return parseCSV(data, opts)
	case "json":
		return parseJSON(data, opts)
	case "ltsv":
		return parseLTSV(data, opts)
	case "yaml":
		return parseYAML(data, opts)
	default:
		return parseText(data, opts)
	}
}

func parseCSV(data string, opts Options) (Table, []string, error) {
	reader := csv.NewReader(strings.NewReader(data))
	reader.Comma = rune(opts.InputDelim[0])

	var rows [][]string
	var columns []string

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, nil, err
		}
		rows = append(rows, record)
	}

	if len(rows) == 0 {
		return nil, nil, nil
	}

	if opts.HasHeader && len(rows) > 0 {
		columns = rows[0]
		rows = rows[1:]
	} else {
		columns = make([]string, len(rows[0]))
		for i := range columns {
			columns[i] = fmt.Sprintf("c%d", i+1)
		}
	}

	var table Table
	for _, row := range rows {
		r := make(Row)
		for i, col := range columns {
			if i < len(row) {
				r[col] = row[i]
			}
		}
		table = append(table, r)
	}

	return table, columns, nil
}

func parseJSON(data string, opts Options) (Table, []string, error) {
	var jsonData interface{}
	err := json.Unmarshal([]byte(data), &jsonData)
	if err != nil {
		return nil, nil, err
	}

	var table Table
	var columns []string

	if arr, ok := jsonData.([]interface{}); ok {
		for _, item := range arr {
			if obj, ok := item.(map[string]interface{}); ok {
				if len(columns) == 0 {
					for key := range obj {
						columns = append(columns, key)
					}
					sort.Strings(columns)
				}
				r := make(Row)
				for key, val := range obj {
					r[key] = val
				}
				table = append(table, r)
			}
		}
	}

	return table, columns, nil
}

func parseLTSV(data string, opts Options) (Table, []string, error) {
	var table Table
	columnSet := make(map[string]bool)
	var columns []string

	scanner := bufio.NewScanner(strings.NewReader(data))
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		obj := make(Row)
		parts := strings.Split(line, "\t")
		for _, part := range parts {
			kv := strings.SplitN(part, ":", 2)
			if len(kv) == 2 {
				key := kv[0]
				obj[key] = kv[1]
				if !columnSet[key] {
					columnSet[key] = true
					columns = append(columns, key)
				}
			}
		}

		table = append(table, obj)
	}

	return table, columns, nil
}

func parseYAML(data string, opts Options) (Table, []string, error) {
	var yamlData []interface{}
	err := yaml.Unmarshal([]byte(data), &yamlData)
	if err != nil {
		return nil, nil, err
	}

	var table Table
	var columns []string

	for _, item := range yamlData {
		if obj, ok := item.(map[string]interface{}); ok {
			if len(columns) == 0 {
				for key := range obj {
					columns = append(columns, key)
				}
				sort.Strings(columns)
			}
			r := make(Row)
			for key, val := range obj {
				r[key] = val
			}
			table = append(table, r)
		}
	}

	return table, columns, nil
}

func parseText(data string, opts Options) (Table, []string, error) {
	return parseCSV(data, opts)
}

type QueryData struct {
	Columns []string
	Rows    []Row
}

func processQuery(query string, tables map[string]Table) QueryData {
	result := QueryData{
		Columns: []string{},
		Rows:    []Row{},
	}

	// Simple implementation - just get first table
	for _, table := range tables {
		if len(table) == 0 {
			return result
		}

		// Extract columns from first row
		firstRow := table[0]
		var columns []string
		for col := range firstRow {
			columns = append(columns, col)
		}
		sort.Strings(columns)

		// Check if SELECT * or specific columns
		selectCols := extractSelectColumns(query)
		if len(selectCols) > 0 {
			columns = selectCols
		}

		result.Columns = columns

		// Apply WHERE clause if any
		filteredRows := []Row{}
		whereClause := extractWhereClause(query)
		for _, row := range table {
			if whereClause == "" || evaluateWhere(whereClause, row) {
				newRow := make(Row)
				for _, col := range columns {
					newRow[col] = row[col]
				}
				filteredRows = append(filteredRows, newRow)
			}
		}

		result.Rows = filteredRows
		return result
	}

	return result
}

func extractSelectColumns(query string) []string {
	// Find SELECT clause
	upQuery := strings.ToUpper(query)
	selectIdx := strings.Index(upQuery, "SELECT")
	if selectIdx == -1 {
		return nil
	}

	fromIdx := strings.Index(upQuery, "FROM")
	if fromIdx == -1 {
		fromIdx = len(query)
	}

	selectPart := query[selectIdx+6 : fromIdx]
	selectPart = strings.TrimSpace(selectPart)

	if selectPart == "*" {
		return nil
	}

	// Parse column list
	cols := strings.Split(selectPart, ",")
	var result []string
	for _, col := range cols {
		col = strings.TrimSpace(col)
		result = append(result, col)
	}
	return result
}

func extractWhereClause(query string) string {
	upQuery := strings.ToUpper(query)
	whereIdx := strings.Index(upQuery, "WHERE")
	if whereIdx == -1 {
		return ""
	}

	afterWhere := query[whereIdx+5:]

	// Find next keyword
	keywords := []string{"GROUP BY", "ORDER BY", "LIMIT"}
	minIdx := len(afterWhere)
	for _, kw := range keywords {
		idx := strings.Index(strings.ToUpper(afterWhere), kw)
		if idx != -1 && idx < minIdx {
			minIdx = idx
		}
	}

	whereClause := afterWhere[:minIdx]
	return strings.TrimSpace(whereClause)
}

func evaluateWhere(whereClause string, row Row) bool {
	// Simple evaluation - handle basic comparisons
	parts := strings.Fields(whereClause)

	if len(parts) >= 3 {
		colName := parts[0]
		operator := parts[1]
		value := strings.Join(parts[2:], " ")
		value = strings.Trim(value, "'\"")

		colVal := fmt.Sprintf("%v", row[colName])

		switch operator {
		case "=":
			return colVal == value
		case "!=", "<>":
			return colVal != value
		case ">":
			return compareValues(colVal, value) > 0
		case "<":
			return compareValues(colVal, value) < 0
		case ">=":
			return compareValues(colVal, value) >= 0
		case "<=":
			return compareValues(colVal, value) <= 0
		}
	}

	return true
}

func compareValues(a, b string) int {
	if a == b {
		return 0
	}
	if a < b {
		return -1
	}
	return 1
}

func writeToStdout(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}
	fmt.Print(output)
	return nil
}

func writeToFile(result *QueryResult, opts Options) error {
	output, err := formatOutput(result, opts)
	if err != nil {
		return err
	}

	err = os.WriteFile(opts.OutputFile, []byte(output), 0644)
	if err != nil {
		return err
	}

	return nil
}

func formatOutput(result *QueryResult, opts Options) (string, error) {
	switch opts.OutputFormat {
	case "csv":
		return formatCSV(result, opts)
	case "json":
		return formatJSON(result, opts)
	case "jsonl":
		return formatJSONL(result, opts)
	case "ltsv":
		return formatLTSV(result, opts)
	case "yaml":
		return formatYAML(result, opts)
	case "md":
		return formatMarkdown(result, opts)
	case "at":
		return formatASCIITable(result, opts)
	case "vf":
		return formatVertical(result, opts)
	case "raw":
		return formatRaw(result, opts)
	default:
		return formatCSV(result, opts)
	}
}

func formatCSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if opts.OutputHeader {
		line := strings.Join(result.Columns, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	for _, row := range result.Rows {
		line := strings.Join(row, opts.OutputDelim)
		output.WriteString(line + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatJSON(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	// Pretty print JSON
	b, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return "", err
	}

	return string(b), nil
}

func formatJSONL(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		b, err := json.Marshal(obj)
		if err != nil {
			return "", err
		}
		output.WriteString(string(b) + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatLTSV(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for _, row := range result.Rows {
		parts := []string{}
		for i, col := range result.Columns {
			parts = append(parts, fmt.Sprintf("%s:%s", col, row[i]))
		}
		output.WriteString(strings.Join(parts, "\t") + "\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatYAML(result *QueryResult, opts Options) (string, error) {
	var data []map[string]interface{}

	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	b, err := yaml.Marshal(data)
	if err != nil {
		return "", err
	}

	return strings.TrimSuffix(string(b), "\n"), nil
}

func formatMarkdown(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("|")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("|\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatASCIITable(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	if len(result.Rows) == 0 {
		return "", nil
	}

	// Calculate column widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	// Top border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padString(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padString(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	// Bottom border
	for i := range result.Columns {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", widths[i]+2))
	}
	output.WriteString("+\n")

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatVertical(result *QueryResult, opts Options) (string, error) {
	var output strings.Builder

	for idx, row := range result.Rows {
		output.WriteString(fmt.Sprintf("---[ %d]", idx+1))
		output.WriteString(strings.Repeat("-", 24) + "\n")

		maxLen := 0
		for _, col := range result.Columns {
			if len(col) > maxLen {
				maxLen = len(col)
			}
		}

		for i, col := range result.Columns {
			output.WriteString(padRight(col, maxLen))
			output.WriteString(" | ")
			output.WriteString(row[i])
			output.WriteString("\n")
		}
	}

	return strings.TrimSuffix(output.String(), "\n"), nil
}

func formatRaw(result *QueryResult, opts Options) (string, error) {
	return formatCSV(result, opts)
}

func padString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	left := (width - len(s)) / 2
	right := width - len(s) - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func analyzeFile(filepath string, opts Options) {
	data, err := os.ReadFile(filepath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
		return
	}

	format := detectFormat(filepath)
	_, columns, err := parseData(format, string(data), opts)
