		if opts.OutputFile != "" {
			err = writeToFile(result, opts)
		} else {
			err = writeToStdout(result, opts)
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
}

