const VERSION = "trdsql version devel"

type Options struct {
	InputFormat    string
	OutputFormat   string
	InputDelim     string
	OutputDelim    string
	HasHeader      bool
	Help           bool
	Version        bool
	Query          string
	QueryFile      string
	InputFile      string
	OutputFile     string
	OutputHeader   bool
	AnalyzeFile    string
	ShowHelp       bool
	Analyze        bool
	AutoDetect     bool
	SkipHeader     int
	PrereadRows    int
	LimitRows      int
	AddRowNum      bool
	NullValue      string
	OutputNull     string
	Debug          bool
	Driver         string
	DSN            string
	Compression    string
	CRLF           bool
	QuoteAll       bool
	Quote          string
	OutWithoutGuess bool
}

type Row map[string]interface{}
type Table []Row

func main() {
	opts := parseFlags()

	if opts.Version {
		fmt.Println(VERSION)
		return
	}

	if opts.Help {
		showUsage()
		os.Exit(2)
	}

	if opts.AnalyzeFile != "" || opts.Analyze {
		filename := opts.AnalyzeFile
		if filename == "" && flag.NArg() > 0 {
			filename = flag.Arg(0)
		}
		if filename != "" {
			analyzeFile(filename, opts)
		}
		return
	}

	// Get query
	query := opts.Query
	if opts.QueryFile != "" {
		data, err := os.ReadFile(opts.QueryFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading query file: %v\n", err)
			os.Exit(1)
		}
		query = strings.TrimSpace(string(data))
	} else if query == "" && flag.NArg() > 0 {
		query = flag.Arg(0)
	}

	if query == "" && opts.InputFile == "" {
		showUsage()
		os.Exit(2)
	}

	// Execute query
	if query != "" {
		result, err := executeQuery(query, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "2026/04/29 04:51:53 %v\n", err)
			os.Exit(1)
		}

		// Output result
		if opts.OutputFile != "" {
			err = writeToFile(result, opts)
		} else {
			err = writeToStdout(result, opts)
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
}

func parseFlags() Options {
	opts := Options{
		InputDelim:   ",",
		OutputDelim:  ",",
		InputFormat:  "guess",
		OutputFormat: "csv",
		Quote:        "\"",
		PrereadRows:  1,
		AutoDetect:   true,
		Driver:       "sqlite3",
	}

	flag.StringVar(&opts.AnalyzeFile, "A", "", "analyze the file but only suggest SQL.")
	flag.StringVar(&opts.AnalyzeFile, "a", "", "analyze the file and suggest SQL.")
	flag.StringVar(&opts.QueryFile, "q", "", "read query from the specified file.")
	flag.StringVar(&opts.InputFile, "t", "", "read table name from the specified file.")
	flag.BoolVar(&opts.Help, "help", false, "display usage information.")
	flag.BoolVar(&opts.Version, "version", false, "display version information.")
	flag.BoolVar(&opts.HasHeader, "ih", false, "the first line is interpreted as column names(CSV only).")
	flag.StringVar(&opts.InputDelim, "id", ",", "field delimiter for input.")
	flag.StringVar(&opts.InputFormat, "ig", "guess", "guess format from extension.")
	flag.StringVar(&opts.OutputDelim, "od", ",", "field delimiter for output.")
	flag.StringVar(&opts.OutputFile, "out", "", "output file name.")
	flag.BoolVar(&opts.OutputHeader, "oh", false, "output column name as header.")
	flag.IntVar(&opts.SkipHeader, "is", 0, "skip header row.")
	flag.IntVar(&opts.PrereadRows, "ir", 1, "number of rows to preread.")
	flag.IntVar(&opts.LimitRows, "ilr", 0, "limited number of rows to read.")
	flag.BoolVar(&opts.AddRowNum, "inum", false, "add row number column.")
	flag.StringVar(&opts.NullValue, "inull", "", "value(string) to convert to null on input.")
	flag.StringVar(&opts.OutputNull, "onull", "", "value(string) to convert from null on output.")
	flag.BoolVar(&opts.Debug, "debug", false, "debug print.")
	flag.StringVar(&opts.Driver, "driver", "sqlite3", "database driver.")
	flag.StringVar(&opts.DSN, "dsn", "", "database driver specific data source name.")
	flag.StringVar(&opts.Compression, "oz", "", "output compression format.")
	flag.BoolVar(&opts.CRLF, "ocrlf", false, "use CRLF for output.")
	flag.BoolVar(&opts.QuoteAll, "oaq", false, "enclose all fields in quotes for output.")
	flag.StringVar(&opts.Quote, "oq", "\"", "quote character for output.")
	flag.BoolVar(&opts.OutWithoutGuess, "out-without-guess", false, "output without guessing (when using -out).")

	// Boolean flags for different format types
	icsv := flag.Bool("icsv", false, "CSV format for input.")
	ijson := flag.Bool("ijson", false, "JSON format for input.")
	iltsv := flag.Bool("iltsv", false, "LTSV format for input.")
	iyaml := flag.Bool("iyaml", false, "YAML format for input.")
	itext := flag.Bool("itext", false, "text format for input.")
	iwidth := flag.Bool("iwidth", false, "width specification format for input.")
	itbln := flag.Bool("itbln", false, "TBLN format for input.")

	ocsv := flag.Bool("ocsv", false, "CSV format for output.")
	ojson := flag.Bool("ojson", false, "JSON format for output.")
	ojsonl := flag.Bool("ojsonl", false, "JSON lines format for output.")
	oltsv := flag.Bool("oltsv", false, "LTSV format for output.")
	omd := flag.Bool("omd", false, "Markdown format for output.")
	oat := flag.Bool("oat", false, "ASCII Table format for output.")
	oyaml := flag.Bool("oyaml", false, "YAML format for output.")
	oraw := flag.Bool("oraw", false, "Raw format for output.")
	ovf := flag.Bool("ovf", false, "Vertical format for output.")
	otbln := flag.Bool("otbln", false, "TBLN format for output.")

	// Other flags
	flag.String("config", "", "configuration file location.")
	flag.String("db", "", "specify db name of the setting.")
	flag.Bool("dblist", false, "display db information.")
	flag.String("ijq", "", "jq expression string for input(JSON/JSONL only).")
	flag.Bool("onowrap", false, "do not wrap long lines(at/md only).")

	flag.Parse()

	// Check for input format flags
	if *icsv {
		opts.InputFormat = "csv"
	} else if *ijson {
		opts.InputFormat = "json"
	} else if *iltsv {
		opts.InputFormat = "ltsv"
	} else if *iyaml {
		opts.InputFormat = "yaml"
	} else if *itext {
		opts.InputFormat = "text"
	} else if *iwidth {
		opts.InputFormat = "width"
	} else if *itbln {
		opts.InputFormat = "tbln"
	}

	// Check for output format flags
	if *ocsv {
		opts.OutputFormat = "csv"
	} else if *ojson {
		opts.OutputFormat = "json"
	} else if *ojsonl {
		opts.OutputFormat = "jsonl"
	} else if *oltsv {
		opts.OutputFormat = "ltsv"
	} else if *omd {
		opts.OutputFormat = "md"
	} else if *oat {
		opts.OutputFormat = "at"
	} else if *oyaml {
		opts.OutputFormat = "yaml"
	} else if *oraw {
		opts.OutputFormat = "raw"
	} else if *ovf {
		opts.OutputFormat = "vf"
	} else if *otbln {
		opts.OutputFormat = "tbln"
	}

	return opts
}

