		opts.OutputFormat = "csv"
	} else if *ojson {
		opts.OutputFormat = "json"
	} else if *ojsonl {
		opts.OutputFormat = "jsonl"
	} else if *oltsv {
		opts.OutputFormat = "ltsv"
	} else if *omd {
		opts.OutputFormat = "md"
	} else if *oat {
		opts.OutputFormat = "at"
	} else if *oyaml {
		opts.OutputFormat = "yaml"
	} else if *oraw {
		opts.OutputFormat = "raw"
	} else if *ovf {
		opts.OutputFormat = "vf"
	} else if *otbln {
		opts.OutputFormat = "tbln"
	}

	return opts
}

