func extractTableInfo(query string) []TableInfo {
	tables := []TableInfo{}

	// Find all FROM clauses with proper case handling
	re := regexp.MustCompile(?i)FROM\s+([^\s,;]+)`)
	matches := re.FindAllStringSubmatch(query, -1)

	for _, match := range matches {
		if len(match) > 1 {
			tableName := strings.Split(match[1], ":")[0]
			tableName = strings.TrimSuffix(tableName, ",")
			tables = append(tables, TableInfo{Name: tableName})
