// parseJSONPreservingOrder parses JSON while preserving key order
func parseJSONPreservingOrder(data string) (Table, []string, error) {
	// Use json.Number to parse and then decode separately
	var arr []interface{}
	decoder := json.NewDecoder(strings.NewReader(data))
	decoder.UseNumber()

	if err := decoder.Decode(&arr); err != nil {
		return nil, nil, err
	}

	var table Table
	var columns []string
	columnMap := make(map[string]bool)

	for _, item := range arr {
		if obj, ok := item.(map[string]interface{}); ok {
			// Preserve order - we need to use json.RawMessage
			// For now, manually extract based on JSON parsing order
			r := make(Row)
			for key, val := range obj {
				r[key] = val
				if !columnMap[key] {
					columnMap[key] = true
					columns = append(columns, key)
				}
			}
			table = append(table, r)
		}
	}

	return table, columns, nil
}
