// extractColumnsFromJSON extracts column names in the order they appear in the JSON
func extractColumnsFromJSON(data string) []string {
	// Find the first object
	objRegex := regexp.MustCompile(`\{[^}]*\}`)
	firstObj := objRegex.FindString(data)
	if firstObj == "" {
		return []string{}
	}

	// Find all quoted keys in order
	keyRegex := regexp.MustCompile(`"([^"]+)"\s*:`)
	matches := keyRegex.FindAllStringSubmatch(firstObj, -1)

	var columns []string
	seen := make(map[string]bool)
	for _, match := range matches {
		key := match[1]
		if !seen[key] {
			columns = append(columns, key)
			seen[key] = true
		}
	}

	return columns
}

// parseJSONWithOrderedColumns parses JSON using pre-extracted column order
func parseJSONWithOrderedColumns(data string) (Table, []string, error) {
	// Extract columns in order
	columns := extractColumnsFromJSON(data)

	// Now unmarshal normally
	var jsonData []interface{}
	err := json.Unmarshal([]byte(data), &jsonData)
	if err != nil {
		return nil, nil, err
	}

	var table Table
	for _, item := range jsonData {
		if obj, ok := item.(map[string]interface{}); ok {
			r := make(Row)
			for key, val := range obj {
				r[key] = val
			}
			table = append(table, r)
		}
	}

	return table, columns, nil
}
