package main

func processQueryWithColumns(query string, tables map[string]Table, columnsMap map[string][]string) QueryData {
	result := QueryData{
		Columns: []string{},
		Rows:    []Row{},
	}

	// Simple implementation - just get first table
	for tableName, table := range tables {
		if len(table) == 0 {
			return result
		}

		// Use the column order from columnsMap
		columns := columnsMap[tableName]
		if len(columns) == 0 {
			// Fallback if not found
			var cols []string
			if len(table) > 0 {
				firstRow := table[0]
				for col := range firstRow {
					cols = append(cols, col)
				}
			}
			columns = cols
		}

		// Check if SELECT * or specific columns
		selectCols := extractSelectColumns(query)
		if len(selectCols) > 0 {
			columns = selectCols
		}

		result.Columns = columns

		// Apply WHERE clause if any
		filteredRows := []Row{}
		whereClause := extractWhereClause(query)
		for _, row := range table {
			if whereClause == "" || evaluateWhere(whereClause, row) {
				newRow := make(Row)
				for _, col := range columns {
					newRow[col] = row[col]
				}
				filteredRows = append(filteredRows, newRow)
			}
		}

		result.Rows = filteredRows
		return result
	}

	return result
}
