	} else if *iltsv {
		inputFmt = "ltsv"
	} else if *iyaml {
		inputFmt = "yaml"
	}

	outputFmt := "csv"
	if *ocsv {
		outputFmt = "csv"
	} else if *ojson {
		outputFmt = "json"
	} else if *ojsonl {
		outputFmt = "jsonl"
	} else if *oltsv {
		outputFmt = "ltsv"
	} else if *omd {
		outputFmt = "md"
	} else if *oat {
		outputFmt = "at"
	} else if *oyaml {
		outputFmt = "yaml"
	} else if *ovf {
		outputFmt = "vf"
	} else if *oraw {
		outputFmt = "raw"
	}

	var query string
	if *queryFile != "" {
		data, err := os.ReadFile(*queryFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		query = strings.TrimSpace(string(data))
	} else if flag.NArg() > 0 {
		query = flag.Arg(0)
	}

	if query == "" {
		showUsage()
		os.Exit(2)
	}

	result, err := executeQuery(query, inputFmt, *hasHeader, *inputDelim)
	if err != nil {
		fmt.Fprintf(os.Stderr, "2026/04/29 04:51:53 %v\n", err)
		os.Exit(1)
	}

	output := formatResult(result, outputFmt, *outputDelim, *outputHeader)

	if *outFile != "" {
		err = os.WriteFile(*outFile, []byte(output), 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	} else {
		fmt.Print(output)
	}
}

type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func executeQuery(query string, inputFmt string, hasHeader bool, inputDelim string) (*QueryResult, error) {
	// Extract table names
	tables := extractTableNames(query)

	tableData := make(map[string]Table)
	tableColumns := make(map[string][]string)

	for _, tableName := range tables {
		data, err := readFile(tableName)
		if err != nil {
			return nil, err
		}

		fmtType := inputFmt
		if fmtType == "guess" {
			fmtType = detectFormat(tableName)
		}

		table, columns, err := parseTable(fmtType, data, hasHeader, inputDelim)
		if err != nil {
			return nil, err
		}

		tableData[tableName] = table
		tableColumns[tableName] = columns
	}

	// Process query (simple implementation)
	return processQuery(query, tableData, tableColumns)
}

func extractTableNames(query string) []string {
	var names []string
	re := regexp.MustCompile(`(?i)FROM\s+([^\s,;]+)`)
	matches := re.FindAllStringSubmatch(query, -1)
	for _, m := range matches {
		names = append(names, strings.Split(m[1], ":")[0])
	}
	return names
}

func readFile(name string) (string, error) {
	if name == "-" {
		data, err := io.ReadAll(os.Stdin)
		return string(data), err
	}
	data, err := os.ReadFile(name)
	return string(data), err
}

func detectFormat(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".csv":
		return "csv"
	case ".json", ".jsonl":
		return "json"
	case ".ltsv":
		return "ltsv"
	case ".yaml", ".yml":
		return "yaml"
	default:
		return "csv"
	}
}

func parseTable(fmt string, data string, hasHeader bool, delim string) (Table, []string, error) {
	switch fmt {
	case "csv":
		return parseCSVTable(data, hasHeader, delim)
	case "json":
		return parseJSONTable(data)
	case "ltsv":
		return parseLTSVTable(data)
	case "yaml":
		return parseYAMLTable(data)
	default:
		return parseCSVTable(data, hasHeader, delim)
	}
}

func parseCSVTable(data string, hasHeader bool, delim string) (Table, []string, error) {
	r := csv.NewReader(strings.NewReader(data))
	if len(delim) > 0 {
		r.Comma = rune(delim[0])
	}

	var rows [][]string
	for {
		record, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, nil, err
		}
		rows = append(rows, record)
	}

	if len(rows) == 0 {
		return nil, nil, nil
	}

	var columns []string
	if hasHeader && len(rows) > 0 {
		columns = rows[0]
		rows = rows[1:]
	} else {
		columns = make([]string, len(rows[0]))
		for i := range columns {
			columns[i] = fmt.Sprintf("c%d", i+1)
		}
	}

	var table Table
	for _, row := range rows {
		r := make(Row)
		for i, col := range columns {
			if i < len(row) {
				r[col] = row[i]
			}
		}
		table = append(table, r)
	}

	return table, columns, nil
}

func parseJSONTable(data string) (Table, []string, error) {
	// Extract columns in order from first object
	columns := extractJSONColumns(data)

	var jsonData []interface{}
	err := json.Unmarshal([]byte(data), &jsonData)
	if err != nil {
		return nil, nil, err
	}

	var table Table
	for _, item := range jsonData {
		if obj, ok := item.(map[string]interface{}); ok {
			r := make(Row)
			for k, v := range obj {
				r[k] = v
			}
			table = append(table, r)
		}
	}

	return table, columns, nil
}

func extractJSONColumns(data string) []string {
	// Find first object
	re := regexp.MustCompile(`\{[^}]*\}`)
	obj := re.FindString(data)
	if obj == "" {
		return []string{}
	}

	// Extract keys in order
	keyRe := regexp.MustCompile(`"([^"]+)"\s*:`)
	matches := keyRe.FindAllStringSubmatch(obj, -1)

	seen := make(map[string]bool)
	var cols []string
	for _, m := range matches {
		key := m[1]
		if !seen[key] {
			cols = append(cols, key)
			seen[key] = true
		}
	}
	return cols
}

func parseLTSVTable(data string) (Table, []string, error) {
	var table Table
	var columns []string
	columnSet := make(map[string]bool)

	scanner := bufio.NewScanner(strings.NewReader(data))
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		r := make(Row)
		parts := strings.Split(line, "\t")
		for _, part := range parts {
			kv := strings.SplitN(part, ":", 2)
			if len(kv) == 2 {
				k, v := kv[0], kv[1]
				r[k] = v
				if !columnSet[k] {
					columnSet[k] = true
					columns = append(columns, k)
				}
			}
		}
		table = append(table, r)
	}

	return table, columns, nil
}

func parseYAMLTable(data string) (Table, []string, error) {
	// Simple YAML parser
	var table Table
	var columns []string
	columnSet := make(map[string]bool)

	scanner := bufio.NewScanner(strings.NewReader(data))
	r := make(Row)
	inItem := false

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "- ") {
			if inItem && len(r) > 0 {
				table = append(table, r)
				r = make(Row)
			}
			inItem = true
			trimmed = strings.TrimPrefix(trimmed, "- ")
		}

		if inItem && strings.Contains(trimmed, ":") {
			idx := strings.Index(trimmed, ":")
			k := strings.TrimSpace(trimmed[:idx])
			v := strings.TrimSpace(trimmed[idx+1:])
			r[k] = v
			if !columnSet[k] {
				columnSet[k] = true
				columns = append(columns, k)
			}
		}
	}

	if inItem && len(r) > 0 {
		table = append(table, r)
	}

	return table, columns, nil
}

func processQuery(query string, tables map[string]Table, tableColumns map[string][]string) (*QueryResult, error) {
	// Get first table
	var firstTable Table
	var firstColumns []string
	for name, table := range tables {
		firstTable = table
		firstColumns = tableColumns[name]
		break
	}

	if len(firstTable) == 0 {
		return &QueryResult{Columns: []string{}, Rows: [][]string{}}, nil
	}

	// Check for SELECT * or specific columns
	selectCols := extractSelectColumns(query)
	if len(selectCols) == 0 {
		selectCols = firstColumns
	}

	// Apply WHERE clause
	whereClause := extractWhereClause(query)
	var filtered Table
	for _, row := range firstTable {
		if whereClause == "" || evalWhere(whereClause, row) {
			filtered = append(filtered, row)
		}
	}

	// Convert to string array
	result := &QueryResult{
		Columns: selectCols,
		Rows:    [][]string{},
	}

	for _, row := range filtered {
		strRow := make([]string, len(selectCols))
		for i, col := range selectCols {
			val := row[col]
			if val == nil {
				strRow[i] = ""
			} else {
				strRow[i] = fmt.Sprintf("%v", val)
			}
		}
		result.Rows = append(result.Rows, strRow)
	}

	return result, nil
}

func extractSelectColumns(query string) []string {
	upQuery := strings.ToUpper(query)
	selectIdx := strings.Index(upQuery, "SELECT")
	if selectIdx == -1 {
		return nil
	}
	fromIdx := strings.Index(upQuery, "FROM")
	if fromIdx == -1 {
		fromIdx = len(query)
	}

	selectPart := strings.TrimSpace(query[selectIdx+6 : fromIdx])
	if selectPart == "*" {
		return nil
	}

	var cols []string
	for _, col := range strings.Split(selectPart, ",") {
		cols = append(cols, strings.TrimSpace(col))
	}
	return cols
}

func extractWhereClause(query string) string {
	upQuery := strings.ToUpper(query)
	idx := strings.Index(upQuery, "WHERE")
	if idx == -1 {
		return ""
	}

	afterWhere := query[idx+5:]
	for _, kw := range []string{"GROUP", "ORDER", "LIMIT"} {
		kidx := strings.Index(strings.ToUpper(afterWhere), kw)
		if kidx != -1 {
			afterWhere = afterWhere[:kidx]
		}
	}

	return strings.TrimSpace(afterWhere)
}

func evalWhere(clause string, row Row) bool {
	parts := strings.Fields(clause)
	if len(parts) < 3 {
		return true
	}

	col := parts[0]
	op := parts[1]
	val := strings.Join(parts[2:], " ")
	val = strings.Trim(val, "'\"")

	rowVal := fmt.Sprintf("%v", row[col])

	switch op {
	case "=":
		return rowVal == val
	case "!=", "<>":
		return rowVal != val
	case ">":
		return rowVal > val
	case "<":
		return rowVal < val
	case ">=":
		return rowVal >= val
	case "<=":
		return rowVal <= val
	}

	return true
}

func formatResult(result *QueryResult, fmt string, delim string, header bool) string {
	switch fmt {
	case "csv":
		return formatCSV(result, delim, header)
	case "json":
		return formatJSON(result)
	case "jsonl":
		return formatJSONL(result)
	case "ltsv":
		return formatLTSV(result)
	case "md":
		return formatMarkdown(result)
	case "at":
		return formatASCIITable(result)
	case "yaml":
		return formatYAML(result)
	case "vf":
		return formatVertical(result)
	case "raw":
		return formatCSV(result, delim, false)
	default:
		return formatCSV(result, delim, header)
	}
}

func formatCSV(result *QueryResult, delim string, header bool) string {
	var output strings.Builder

	if header {
		output.WriteString(strings.Join(result.Columns, delim))
		output.WriteString("\n")
	}

	for _, row := range result.Rows {
		output.WriteString(strings.Join(row, delim))
		output.WriteString("\n")
	}

	return strings.TrimSuffix(output.String(), "\n")
}

func formatJSON(result *QueryResult) string {
	var data []map[string]interface{}
	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		data = append(data, obj)
	}

	b, _ := json.MarshalIndent(data, "", "  ")
	return string(b)
}

func formatJSONL(result *QueryResult) string {
	var output strings.Builder
	for _, row := range result.Rows {
		obj := make(map[string]interface{})
		for i, col := range result.Columns {
			obj[col] = row[i]
		}
		b, _ := json.Marshal(obj)
		output.WriteString(string(b))
		output.WriteString("\n")
	}
	return strings.TrimSuffix(output.String(), "\n")
}

func formatLTSV(result *QueryResult) string {
	var output strings.Builder
	for _, row := range result.Rows {
		var parts []string
		for i, col := range result.Columns {
			parts = append(parts, col+":"+row[i])
		}
		output.WriteString(strings.Join(parts, "\t"))
		output.WriteString("\n")
	}
	return strings.TrimSuffix(output.String(), "\n")
}

func formatYAML(result *QueryResult) string {
	var output strings.Builder
	for i, row := range result.Rows {
		if i > 0 {
			output.WriteString("- ")
		} else {
			output.WriteString("- ")
		}
		for j, col := range result.Columns {
			output.WriteString(col)
			output.WriteString(": ")
			output.WriteString(row[j])
			if j < len(result.Columns)-1 {
				output.WriteString("\n  ")
			} else if i < len(result.Rows)-1 {
				output.WriteString("\n")
			}
		}
		if i < len(result.Rows)-1 {
			output.WriteString("\n")
		}
	}
	output.WriteString("\n")
	return strings.TrimSuffix(output.String(), "\n")
}

func formatMarkdown(result *QueryResult) string {
	if len(result.Rows) == 0 {
		return ""
	}

	// Calculate widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	var output strings.Builder

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padCenter(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for _, w := range widths {
		output.WriteString("|")
		output.WriteString(strings.Repeat("-", w+2))
	}
	output.WriteString("|\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padLeft(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	return strings.TrimSuffix(output.String(), "\n")
}

func formatASCIITable(result *QueryResult) string {
	if len(result.Rows) == 0 {
		return ""
	}

	// Calculate widths
	widths := make([]int, len(result.Columns))
	for i, col := range result.Columns {
		widths[i] = len(col)
	}
	for _, row := range result.Rows {
		for i, val := range row {
			if len(val) > widths[i] {
				widths[i] = len(val)
			}
		}
	}

	var output strings.Builder

	// Top border
	for _, w := range widths {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", w+2))
	}
	output.WriteString("+\n")

	// Header
	for i, col := range result.Columns {
		output.WriteString("| ")
		output.WriteString(padCenter(col, widths[i]))
		output.WriteString(" ")
	}
	output.WriteString("|\n")

	// Separator
	for _, w := range widths {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", w+2))
	}
	output.WriteString("+\n")

	// Rows
	for _, row := range result.Rows {
		for i, val := range row {
			output.WriteString("| ")
			output.WriteString(padLeft(val, widths[i]))
			output.WriteString(" ")
		}
		output.WriteString("|\n")
	}

	// Bottom border
	for _, w := range widths {
		output.WriteString("+")
		output.WriteString(strings.Repeat("-", w+2))
	}
	output.WriteString("+\n")

	return strings.TrimSuffix(output.String(), "\n")
}

func formatVertical(result *QueryResult) string {
	var output strings.Builder

	for idx, row := range result.Rows {
		output.WriteString(fmt.Sprintf("---[ %d]", idx+1))
		output.WriteString(strings.Repeat("-", 24))
		output.WriteString("\n")

		maxLen := 0
		for _, col := range result.Columns {
			if len(col) > maxLen {
				maxLen = len(col)
			}
		}

		for i, col := range result.Columns {
			output.WriteString(padRight(col, maxLen))
			output.WriteString(" | ")
			output.WriteString(row[i])
			output.WriteString("\n")
		}
	}

	return strings.TrimSuffix(output.String(), "\n")
}

func padCenter(s string, width int) string {
	if len(s) >= width {
		return s
	}
	left := (width - len(s)) / 2
	right := width - len(s) - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padLeft(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func showUsage() {
	fmt.Fprintf(os.Stderr, `trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

