	} else if *iyaml {
		inputFmt = "yaml"
	}

	outputFmt := "csv"
	if *ocsv {
		outputFmt = "csv"
	} else if *ojson {
		outputFmt = "json"
	} else if *ojsonl {
		outputFmt = "jsonl"
	} else if *oltsv {
		outputFmt = "ltsv"
	} else if *omd {
		outputFmt = "md"
	} else if *oat {
		outputFmt = "at"
	} else if *oyaml {
		outputFmt = "yaml"
	} else if *ovf {
		outputFmt = "vf"
	} else if *oraw {
		outputFmt = "raw"
	}

	var query string
	if *queryFile != "" {
		data, err := os.ReadFile(*queryFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		query = strings.TrimSpace(string(data))
	} else if flag.NArg() > 0 {
		query = flag.Arg(0)
	}

	if query == "" {
		showUsage()
		os.Exit(2)
	}

	result, err := executeQuery(query, inputFmt, *hasHeader, *inputDelim)
	if err != nil {
		fmt.Fprintf(os.Stderr, "2026/04/29 04:51:53 %v\n", err)
		os.Exit(1)
	}

	output := formatResult(result, outputFmt, *outputDelim, *outputHeader)

